import itertools
from functools import lru_cache
def leafpaths(pts,adj):
    leaves=[p for p in pts if len(adj[p])==1]
    res={}
    for a,b in itertools.combinations(leaves,2):
        # BFS longest simple path too expensive; use DFS with limit
        best=[]
        def dfs(cur,vis,path):
            nonlocal best
            if len(path)>len(best): best=path[:]
            for n in adj[cur]:
                if n not in vis:
                    vis.add(n); path.append(n); dfs(n,vis,path); path.pop(); vis.remove(n)
        dfs(a,{a},[a])
        res[(a,b)]=best
    return res
