def ham(pts,adj):
    leaves=[p for p in pts if len(adj[p])==1]
    res=[]
    def dfs(cur,vis,path):
        if len(path)==len(pts):
            res.append(path[:]); return True
        for n in adj[cur]:
            if n not in vis:
                vis.add(n); path.append(n)
                if dfs(n,vis,path): return True
                path.pop(); vis.remove(n)
        return False
    for a in leaves:
        if dfs(a,{a},[a]): break
    return res
