from collections import deque
def holes(grid,H,W):
    zero={(r,c) for r in range(H) for c in range(W) if grid[r][c]==0}
    outb=set(); q=deque()
    for (r,c) in zero:
        if r in(0,H-1) or c in(0,W-1): q.append((r,c)); outb.add((r,c))
    while q:
        r,c=q.popleft()
        for d in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(r+d[0],c+d[1])
            if n in zero and n not in outb: outb.add(n); q.append(n)
    return zero-outb
