def rings(grid,H,W):
    # rectangles (2-row or 2-col, or any?) whose perimeter is covered by 5s+0s with 0s being fillable, no interior 0-conflict
    res=[]
    for r0 in range(H):
        for c0 in range(W):
            for h in range(2,H-r0+1):
                for w in range(2,W-c0+1):
                    r1,c1=r0+h-1,c0+w-1
                    per=[(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                         if r in(r0,r1) or c in(c0,c1)]
                    interior=[(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)]
                    if any(grid[r][c]==0 for r,c in interior): continue
                    gaps=[p for p in per if grid[p[0]][p[1]]==0]
                    if gaps and all(grid[p[0]][p[1]]==5 for p in per if p not in gaps):
                        res.append((gaps,per,h,w,r0,c0))
    return res
